import Link from 'next/link'
import { notFound } from 'next/navigation'
import { getProduct, products } from '@/lib/products'

/**
 * A dynamic route: the folder is called [slug], so the URL /products/usb-c-hub
 * gives us params.slug === 'usb-c-hub'.
 *
 * NOTE! In Next.js 15+ params is a PROMISE, so the component is async and we await it.
 * PageProps<'/1-routing/products/[slug]'> is generated by Next (npx next typegen),
 * and types params for this exact route.
 */
export default async function ProductPage({ params }: PageProps<'/1-routing/products/[slug]'>) {
  const { slug } = await params
  const product = getProduct(slug)

  // notFound() stops rendering and shows the nearest not-found.tsx
  if (!product) {
    notFound()
  }

  return (
    <>
      <Link href="/1-routing/products" className="text-sm text-indigo-700 hover:underline">
        ← All products
      </Link>
      <h1 className="mt-2 text-2xl font-bold">{product.name}</h1>
      <p className="text-slate-600">{product.category}</p>
      <p className="mt-4 text-3xl font-bold">{product.price} kr</p>
      <p className="mt-2 text-slate-700">{product.description}</p>
    </>
  )
}

/**
 * generateStaticParams tells Next which pages it can build in advance (at build time).
 * Without it, the page is rendered on demand. Try `npm run build` and look at the output.
 */
export function generateStaticParams() {
  return products.map((product) => ({ slug: product.slug }))
}
